import { useNavigate } from "react-router-dom";
import Button from "../components/Button";

export default function QuizOptionsPage() {
  const navigate = useNavigate();

  return (
    <div className="space-y-6">
      <h2 className="text-3xl font-semibold">Choose Quiz Type</h2>

      <Button onClick={() => navigate("/quiz?type=today")}>
        📅 Today's Tasks Quiz
      </Button>

      <Button onClick={() => navigate("/quiz?type=phase")}>
        📘 Phase Quiz
      </Button>

      <Button onClick={() => navigate("/quiz?type=full")}>
        🌍 Full Learning Quiz
      </Button>
    </div>
  );
}
